173	    /// The associated scope, if this is a function, type, or module.
174	    pub fn scope(&self) -> Option<&Scope> {
175	        match self {
176	            Self::Func(func) => func.scope(),
177	            Self::Type(ty) => Some(ty.scope()),
178	            Self::Module(module) => Some(module.scope()),
179	            _ => None,
180	        }
181	    }
