183	    /// Try to extract documentation for the value.
184	    pub fn docs(&self) -> Option<&'static str> {
185	        match self {
186	            Self::Func(func) => func.docs(),
187	            Self::Type(ty) => Some(ty.docs()),
188	            _ => None,
189	        }
190	    }
